package android.os;import java.util.*;public class Bundle extends HashMap<String,Object>{public Bundle(){}public Bundle(Bundle other){super(other);}public void putString(String k,String v){put(k,v);}public void putLong(String k,long v){put(k,Long.valueOf(v));}public void putBoolean(String k,boolean v){put(k,Boolean.valueOf(v));}public String getString(String k){return (String)get(k);}public String getString(String k,String fallback){String value=getString(k);return value==null?fallback:value;}public long getLong(String k){return (Long)getOrDefault(k,Long.valueOf(0));}public boolean getBoolean(String k){return Boolean.TRUE.equals(get(k));}}
